463	class _DashPainter extends CustomPainter {
464	  _DashPainter(this.color, this.radius);
465	  final Color color;
466	  final double radius;
467	
468	  @override
469	  void paint(Canvas canvas, Size size) {
470	    final rect = (Offset.zero & size).deflate(1);
471	    final r = math.min(radius, rect.shortestSide / 2);
472	    final path = Path()
473	      ..addRRect(RRect.fromRectAndRadius(rect, Radius.circular(r)));
474	    final paint = Paint()
475	      ..color = color
476	      ..style = PaintingStyle.stroke
477	      ..strokeWidth = 2;
478	    for (final metric in path.computeMetrics()) {
479	      for (var d = 0.0; d < metric.length; d += 10) {
480	        canvas.drawPath(
481	          metric.extractPath(d, math.min(d + 6, metric.length)),
482	          paint,
483	        );
484	      }
485	    }
486	  }
487	
488	  @override
489	  bool shouldRepaint(covariant _DashPainter old) =>
490	      old.color != color || old.radius != radius;
491	}
