/// A source's tab. Only the selected one is filled (light on plum, the highest contrast on the
/// screen); the rest are quiet outlines, and planned-only sources are muted with `Soon`.
class _SourceTab extends StatelessWidget {
  const _SourceTab({
    required this.source,
    required this.selected,
    required this.onTap,
  });
  final MediaSource source;
  final bool selected;
  final VoidCallback? onTap;

  @override
  Widget build(BuildContext context) {
    final soon = !source.available;
    Widget tab = Container(
      height: 40,
      padding: const EdgeInsets.symmetric(horizontal: 16),
      decoration: BoxDecoration(
        color: selected ? WtColors.text : null,
        borderRadius: BorderRadius.circular(WtRadius.pill),
        border: Border.all(
          color: selected ? WtColors.text : WtColors.line,
          width: 2,
        ),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(
            source.label,
            style: TextStyle(
              fontSize: 14,
              fontWeight: FontWeight.w800,
              color: selected
                  ? WtColors.plum
                  : soon
                  ? WtColors.tx3
                  : WtColors.tx2,
            ),
          ),
          if (soon) ...[const SizedBox(width: 8), const _SoonTag()],
        ],
      ),
    );
    if (soon) tab = Opacity(opacity: 0.6, child: tab);
    return Semantics(
      selected: selected,
      child: WtTap(
        onTap: onTap,
        radius: WtRadius.pill,
        dimWhenDisabled: false,
        tooltip: soon ? '${source.label} is coming soon' : null,
        child: tab,
      ),
    );
  }
}

class _SoonTag extends StatelessWidget {
