/// Title, subtitle and duration under the art; `Play` / `Queue` over it on hover or selection.
class _MediaCard extends StatefulWidget {
  const _MediaCard({
    required this.item,
    required this.poster,
    required this.selected,
    required this.queued,
    required this.busy,
